package anchors

import "testing"

// These independent expectations make removal of a chunk-chain rule fail.
func TestChunkChainAnchors(t *testing.T) {
	const implement = ".agents/commands/bench-implement-spec.md"
	anchorHarness{group: AfterImplementSpec, rules: []anchorRule{
		{file: implement, section: "Build", needle: "After each ticket commit, run `bench worktree exec <target> -- bench preflight build <slug> --base <chunk-base> --source-tip <tip>`.", want: "chunk chain: build preflight runs through the worktree with the chunk's --base and --source-tip after each ticket commit"},
		{file: implement, section: "Build", needle: "The author commits the verification and probe record before the axis dispatch.", want: "chunk chain: the probe record commits before the axis dispatch"},
		{file: implement, section: "Build", needle: "Prepare the review charge from that record commit. The sequence is the author record commit, then the review charge, then the axis dispatch.", want: "chunk chain: the review charge follows the author record commit and precedes the axis dispatch"},
		{file: implement, section: "Build", needle: "Prepare the review charge before the author record commit.", want: "chunk chain: the Build section puts the review charge before the author record commit", forbidden: true},
		{file: implement, section: "Build", needle: "A build dispatches no light-path fix while it runs.", want: "chunk chain: the build dispatches no light-path fix"},
		{file: implement, section: "Build", needle: "A fix that the build's own outcome needs lands as the build's own commit under `.bench/BENCH.md`'s fix-don't-park rule.", want: "chunk chain: a fix the build needs lands as the build's own commit"},
		{file: "docs/adr/0023-each-ticket-gets-a-fresh-author.md", needle: "A build dispatches no light-path fix while it runs.", want: "chunk chain: ADR 0023 dropped the build's light-path hold"},
		{file: "docs/adr/0023-each-ticket-gets-a-fresh-author.md", needle: "and so does a phase that needs a learning's fix.", want: "chunk chain: ADR 0023 restored the unscoped light-path dispatch of a phase", forbidden: true},
		{file: implement, section: "Land", needle: "Plan commits land before the ticket merge, and a `main` merge lands before the first chunk or as a recorded fold. Only record commits, recorded folds, and comment-only corrections follow the chunk tip.", want: "chunk chain: only record commits, recorded folds, and comment-only commits follow the chunk tip"},
		{file: implement, section: "Land", needle: "A build folds `main` with `bench worktree merge --from main <target>` before the first chunk, or in a chunk gap before the first dispatch of the next chunk.", want: "chunk chain: a build folds main only before the first chunk or in a chunk gap"},
		{file: implement, section: "Land", needle: "The Command Notes of `.bench/BENCH-reference.md` state how a chunk gap opens and closes.", want: "chunk chain: the implement phase dropped its pointer to the chunk gap notes"},
		{file: implement, section: "Land", needle: "Each fold after the first chunk takes `bench record fold` before the next commit.", want: "chunk chain: each fold after the first chunk takes bench record fold"},
		{file: implement, section: "Land", needle: "After the last freeze, `main` moves only through the reviewer's landing override, and a recorded fold covers the completion source without a refreeze.", want: "chunk chain: after the last freeze main moves only through the landing override"},
		{file: implement, section: "Land", needle: "A build never folds `main` between two tickets of a chunk.", want: "chunk chain: no main fold between two tickets of a chunk"},
		{file: implement, section: "Land", needle: "Inside a chunk, the post-ticket preflight passes the chunk's `--base` and the current `--source-tip`, so a moved `main` does not route a fold.", want: "chunk chain: the in-chunk preflight passes the chunk base and the current source tip"},
		{file: implement, needle: "A build folds `main` only before the first chunk, at the start of the last chunk, or before the completion landing.", want: "chunk chain: the implement phase restored the main fold at the start of the last chunk", forbidden: true},
		{file: implement, needle: "The fold at the start of the last chunk comes before its first ticket dispatch.", want: "chunk chain: the implement phase restored the last-chunk fold before its first ticket dispatch", forbidden: true},
		{file: implement, needle: "When `main` moves during the build, the `main` fold and the reconciliation commit join the review delta of the last chunk.", want: "chunk chain: the implement phase restored the fold in the review delta of the last chunk", forbidden: true},
		{file: implement, needle: "A fold before the completion landing follows `/bench-review-implementation` step 1, and the last chunk refreezes.", want: "chunk chain: the implement phase restored the refreeze of the last chunk after a fold", forbidden: true},
		{file: ".agents/skills/bench-craft-delegate/SKILL.md", needle: "During a build, `/bench-implement-spec` owns the fold timing, and a ticket charge starts without this fold.", want: "chunk chain: craft-delegate leaves the build fold timing to the implement phase"},
		{file: ".agents/skills/bench-craft-tickets/SKILL.md", needle: "After each chunk, Review freezes the chunk base and the current tip.", want: "chunk chain: craft-tickets restored the review as the chunk freezer", forbidden: true},
		{file: ".bench/BENCH-reference.md", needle: "Review freezes each chunk's base and current tip.", want: "chunk chain: the reference restored the review as the chunk freezer", forbidden: true},
		{file: ".agents/skills/bench-craft-tickets/SKILL.md", needle: "In each chunk, the last ticket's author freezes the chunk base and the current tip.", want: "chunk chain: craft-tickets dropped the last ticket's author as the chunk freezer"},
		{file: ".bench/BENCH-reference.md", needle: "The last ticket's author freezes each chunk's base and current tip.", want: "chunk chain: the reference dropped the last ticket's author as the chunk freezer"},
		{file: implement, section: "Land", needle: "Write the ordinary assessment record before the `bench worktree land` step, and append the landing evidence after it.", want: "chunk chain: the assessment record precedes the landing"},
		{file: implement, section: "Land", needle: "After the last ticket of a chunk, that ticket's author freezes the chunk and records the chunk entry with `bench record ticket`.", want: "chunk chain: the last ticket's author records the chunk entry at the freeze"},
		{file: implement, section: "Build", needle: "The last ticket's author performs that freeze, as the Land section states.", want: "chunk chain: the Build section dropped the last ticket's author as the freeze owner"},
		{file: implement, needle: "When the orchestrator freezes a chunk after its last ticket", want: "chunk chain: the implement phase restored the orchestrator's chunk record", forbidden: true},
		{file: implement, section: "Land", needle: "Before a successor chunk starts, run `bench gate --checkpoint specs/<slug>/spec.md --chunk <id>`.", want: "chunk chain: the chunk checkpoint gate runs before a successor chunk"},
		{file: implement, needle: "--chunk <id>` before the successor", want: "chunk chain: the implement phase restored the chunk checkpoint gate for every chunk", forbidden: true},
		{file: implement, section: "Land", needle: "The last chunk runs no chunk checkpoint gate, because the complete checkpoint that `/bench-final-check` owns grades every chunk again.", want: "chunk chain: the last chunk closes through the complete checkpoint alone"},
		{file: implement, section: "Land", needle: "The last chunk keeps its chunk entry, its verification entries, and its three review entries.", want: "chunk chain: the last chunk keeps its chunk, verification, and review entries"},
		{file: implement, needle: "not code, and it refreshes `bench handoff` at each chunk checkpoint and at the final reconciliation.", want: "fresh ticket author: bench-implement-spec.md dropped the handoff refresh at each chunk checkpoint or at the final reconciliation"},
		{file: "docs/adr/0023-each-ticket-gets-a-fresh-author.md", needle: "It refreshes the session handoff at each chunk checkpoint and at the final reconciliation", want: "chunk chain: ADR 0023 dropped the handoff refresh at the final reconciliation"},
		{file: "README.md", needle: "more -->|\"yes; chunk checkpoint\"| chunk", want: "chunk chain: the README chunk flow dropped the chunk checkpoint on the successor edge"},
		{file: "README.md", needle: "\"none; chunk checkpoint\"", want: "chunk chain: the README chunk flow restored the chunk checkpoint on the no-successor edge", forbidden: true},
		{file: "README.md", needle: "chunk checkpoint\"| accepted", want: "chunk chain: the README chunk flow put the chunk checkpoint on the edge into accepted", forbidden: true},
		{file: implement, section: "Land", needle: "Each ticket author then writes its verification entries at that chunk source with `bench record ticket`.", want: "chunk chain: each ticket author records its verification at the chunk source"},
		{file: implement, section: "Land", needle: "The orchestrator keeps one build log at the primary checkout's `capture/build-log/<slug>.log`.", want: "chunk chain: the orchestrator keeps one build log in the primary checkout's capture folder"},
		{file: implement, section: "Land", needle: "For each reviewer direction that saves a step, it appends one line that names the direction and the step that it removed.", want: "chunk chain: the build log takes one line for each reviewer direction that saves a step"},
		{file: implement, section: "Land", needle: "The retro author reads that log.", want: "chunk chain: the retro author reads the build log"},
		{file: implement, section: "`--full <spec>`", needle: "A green chunk checkpoint and its handoff refresh are not a phase exit. The orchestrator continues into the successor chunk in the same turn, and it stops only on a `craft-line` stop condition.", want: "chunk chain: a green chunk checkpoint is not a phase exit"},
		{file: ".agents/commands/bench-review-implementation.md", section: "Process", step: 1, needle: "A later plan commit is never a chunk base.", want: "chunk chain: a plan commit is never a chunk base"},
		{file: ".agents/commands/bench-review-implementation.md", section: "Process", step: 1, needle: "Merge `main` into the source before the first chunk. `/bench-implement-spec` owns each later fold point and its `bench record fold` step. The review chain accepts a recorded fold between two chunks and after the last chunk.", want: "chunk chain: a main merge lands before the first chunk or as a recorded fold"},
		{file: ".agents/commands/bench-review-implementation.md", needle: "A later chunk base holds the tree of the accepted predecessor tip, so the review chain refuses a `main` merge between two chunks.", want: "chunk chain: the review phase restored the chain refusal of a main merge between two chunks", forbidden: true},
		{file: ".agents/commands/bench-review-implementation.md", needle: "The fold joins the review delta of the last chunk.", want: "chunk chain: the review phase restored the fold in the review delta of the last chunk", forbidden: true},
		{file: ".agents/commands/bench-review-implementation.md", section: "Review modes", needle: "A chunk that ends on a repair takes one confirming round of all three axes at its final tip.", want: "chunk chain: a repair-ending chunk takes one confirming round"},
		{file: ".agents/commands/bench-review-implementation.md", needle: "A confirming round reads only the repair delta and examines only the findings that its charge names.", want: "narrow review axis: bench-review-implementation.md lets a confirming round read more than the repair delta or examine more than its named findings"},
		{file: ".agents/commands/bench-review-implementation.md", section: "Review modes", needle: "Its charge names those findings and the folds to confirm.", want: "chunk chain: a confirming round's charge dropped its named findings or its folds"},
		{file: ".agents/commands/bench-review-implementation.md", needle: "look first for duplicated knowledge in the repair delta", want: "chunk chain: the review phase restored the Standards first look that widens a confirming round", forbidden: true},
		{file: ".agents/commands/bench-review-implementation.md", section: "Review modes", needle: "A test-only repair whose coordinator probe bites closes through `bench record confirmation` and takes no confirming round.", want: "chunk chain: a test-only repair with a biting coordinator probe took a confirming round"},
		{file: ".agents/commands/bench-review-implementation.md", section: "Review modes", needle: "When every accepted finding of a round falls on one ticket, one combined repair charge carries them all.", want: "chunk chain: a one-ticket round dropped its one combined repair charge"},
		{file: ".agents/commands/bench-review-implementation.md", section: "Review modes", needle: "That charge holds the findings of every axis and goes to that ticket's repair session.", want: "chunk chain: the combined repair charge dropped the findings of every axis or the ticket's repair session"},
		{file: ".agents/commands/bench-review-implementation.md", section: "Review modes", needle: "When the accepted findings fall on several tickets, each affected ticket keeps its own repair session under `.bench/BENCH.md`'s repair rule.", want: "chunk chain: a multi-ticket round dropped the repair session of each affected ticket"},
		{file: ".agents/skills/bench-craft-delegate/references/delegation-discipline.md", needle: "A re-review charge names the findings and the folds to confirm, and the round examines only those findings.", want: "chunk chain: delegation-discipline dropped the named findings and folds of a re-review charge"},
		{file: ".agents/skills/bench-craft-delegate/references/delegation-discipline.md", needle: "asks only for findings above the blocking bar", want: "chunk chain: delegation-discipline restored the blocking-bar scope of a re-review", forbidden: true},
		{file: ".agents/commands/bench-review-implementation.md", section: "Process", step: 4, needle: "In the default mode, spawn the axes in parallel sub-agents.", want: "chunk chain: review step 4 dropped the parallel dispatch of the axes"},
		{file: ".agents/commands/bench-review-implementation.md", section: "Process", step: 4, needle: "On one shared tree, only one axis runs tests or probes while the other axes read.", want: "chunk chain: one axis probes a shared tree"},
		{file: ".agents/commands/bench-review-implementation.md", section: "Process", step: 6, needle: "A review worktree moves to the record commit, and the frozen pair still names the source tip.", want: "chunk chain: the frozen pair keeps the source tip after the record commit"},
		{file: ".agents/commands/bench-review-implementation.md", section: "Process", step: 6, needle: "Write each completed chunk, verification, review, and amendment entry with `bench record`, not with hand-built JSON.", want: "chunk chain: step 6 writes each completed entry with bench record"},
		{file: ".agents/commands/bench-review-implementation.md", section: "Process", step: 6, needle: "The last ticket's author writes the frozen pair and its digests with `bench record ticket`, and `bench record review` appends one axis result.", want: "chunk chain: step 6 dropped the last ticket's author as the writer of the frozen pair"},
		{file: ".agents/commands/bench-review-implementation.md", section: "Process", step: 6, needle: "`bench record chunk` writes one chunk entry, `bench record excerpt` stages the last retained response as one excerpt, and `bench record ticket` writes one ticket's entries.", want: "chunk chain: step 6 dropped the chunk, excerpt, or ticket record form"},
		{file: ".agents/commands/bench-review-implementation.md", needle: "Preflight supplies the source and plan digests.", want: "chunk chain: the review phase restored the preflight digest sentence", forbidden: true},
		{file: ".agents/commands/bench-review-implementation.md", needle: "Record the performer, role, model, effort, frozen base and tip, source, state, and native result.", want: "chunk chain: the review phase restored the hand-recording field sentence", forbidden: true},
		{file: ".agents/commands/bench-review-implementation.md", needle: "Embed the minimal native excerpt and its SHA-256 digest; local logs are supplemental evidence.", want: "chunk chain: the review phase restored the hand-embedded excerpt sentence", forbidden: true},
		{file: ".agents/skills/bench-craft-line/references/bounded-repair-policy.md", section: "Classification and completion", needle: "After the acceptance rows of a chunk prove, the chunk permits at most one hardening cycle.", want: "chunk chain: the hardening cap is one cycle"},
	}}.check(t)
}
